import { describe, expect, it } from 'vitest';

import { EndOfStreamError, ProblemReadingDatabaseFile } from '../../src/format/errors';
import { packString } from '../../src/format/flatpack';
import { FlatPackReader } from '../../src/format/reader';
import { concat } from '../helpers/bytes';

const encoder = new TextEncoder();

describe('FlatPackReader', () => {
  it('tracks remaining bytes until EOF', () => {
    const reader = new FlatPackReader(packString('hi'));
    expect(reader.atEof()).toBe(false);
    reader.readString();
    expect(reader.atEof()).toBe(true);
    expect(reader.remaining).toBe(0);
  });

  it('reads consecutive fields', () => {
    const reader = new FlatPackReader(
      concat(packString('a'), packString('bb'), packString('ccc')),
    );
    expect(reader.readString()).toBe('a');
    expect(reader.readString()).toBe('bb');
    expect(reader.readString()).toBe('ccc');
    expect(reader.atEof()).toBe(true);
  });

  it('throws EndOfStreamError when reading past a clean EOF', () => {
    const reader = new FlatPackReader(new Uint8Array([]));
    expect(() => reader.readString()).toThrow(EndOfStreamError);
  });

  it('readEof() throws at a clean end of stream', () => {
    expect(() => new FlatPackReader(new Uint8Array([])).readEof()).toThrow(
      EndOfStreamError,
    );
  });

  it('throws ProblemReadingDatabaseFile for a truncated field', () => {
    // declares 5 bytes but only supplies 2
    const reader = new FlatPackReader(encoder.encode('0005hi'));
    expect(() => reader.readString()).toThrow(ProblemReadingDatabaseFile);
  });

  it('throws ProblemReadingDatabaseFile for a non-numeric length prefix', () => {
    const reader = new FlatPackReader(encoder.encode('xxxx'));
    expect(() => reader.readString()).toThrow(ProblemReadingDatabaseFile);
  });

  it('throws ProblemReadingDatabaseFile for a truncated length prefix', () => {
    const reader = new FlatPackReader(encoder.encode('00'));
    expect(() => reader.readString()).toThrow(ProblemReadingDatabaseFile);
  });
});

describe('FlatPackReader.readInt', () => {
  it('parses the decimal string', () => {
    expect(new FlatPackReader(packString('42')).readInt()).toBe(42);
  });

  it('rejects a non-integer field', () => {
    expect(() => new FlatPackReader(packString('4x2')).readInt()).toThrow(
      ProblemReadingDatabaseFile,
    );
  });
});
